-- Website Governance Plan V3 (October 7, 2026 Website Standards and Leadership Support meeting).
-- The transcript upload had filed the meeting only as a separate notes doc under the Playbook;
-- V asked (2026-10-27) for the plan itself to carry it. Adds V3 as the current version (V2
-- archived in the version menu) from the transcript, recap PDF, and deck. Previous content is
-- kept in bcps_doc_revisions (metadata.revision_before_v3). Guarded on the pre-V3 md5.
-- Applied 2026-10-27 via the one-time function ve-once-governance-v3 (now a 410 stub).

with cur as (
  select id, slug, content c from public.briefings where id='b525e06a-8849-49d0-9f76-3e1051de3f50' and md5(content)='4f167f644d5d1891a5561a3e7caf8efe'
), rev as (
  insert into public.bcps_doc_revisions (slug, content, replaced_by_email) select slug, c, 'vegan@lesaruss.com' from cur returning id
), v3 as (
  select replace(replace(convert_from(decode('','base64'),'UTF8'),
    '{{BACKGROUND}}', '  <!-- BACKGROUND -->' || split_part(split_part(c, '  <!-- BACKGROUND -->', 2), '  <!-- OPEN ISSUES -->', 1)),
    '{{BP_GOV}}', '  <!-- INDUSTRY BEST PRACTICES -->' || split_part(split_part(c, '  <!-- INDUSTRY BEST PRACTICES -->', 2), '  <!-- NEXT STEPS -->', 1)) as block
  from cur
)
update public.briefings b set
  content = replace(replace(replace(replace(cur.c,
      '</style>', convert_from(decode('','base64'),'UTF8') || '</style>'),
      '<option value="v2">V2 - June 10, 2026 (Current)</option>',
      '<option value="v3">V3 - October 7, 2026 (Current)</option>' || chr(10) || '      <option value="v2">V2 - June 10, 2026 (Archived)</option>'),
      '<div id="version-v2" class="version-content active">', '<div id="version-v2" class="version-content">'),
      '<!-- ===== V2 ===== -->', v3.block || '<!-- ===== V2 ===== -->'),
  updated_at = now(),
  metadata = b.metadata || jsonb_build_object('version', 3, 'last_meeting', '2026-10-07', 'revision_before_v3', (select id from rev))
from cur, v3 where b.id = cur.id
returning md5(b.content), length(b.content);